memo = {}
accumulated = 0

def walk(depth, active, need):
    nonlocal accumulated
    if depth == length:
        return 1
    if not active:
        return 0
    widest = 0
    for box in active:
        if suffix[box][depth] > widest:
            widest = suffix[box][depth]
    if widest >= need:
        raise _Exceeded()
    key = (depth, active)
    found = memo.get(key)
    if found is not None:
        return found
    points = set()
    for box in active:
        for start, end in box[depth]:
            points.add(start)
            points.add(end+1)
    points = sorted(points)
    total = 0
    for index in range(len(points)-1):
        low = points[index]
        high = points[index+1]-1
        values = (high-low+1) - (1 if low <= PADDING <= high else 0)
        if values <= 0:
            continue
        sub = tuple(box for box in active if _covers(box[depth], low, high))
        if not sub:
            continue
        inner = walk(depth+1, sub, limit-accumulated)
        contribution = values*inner
        total += contribution
        accumulated += contribution
        if accumulated >= limit:
            raise _Exceeded()
